#!/usr/bin/env python3
"""Retain DCN201 blend defaults and register packing without hardware access."""
import argparse
import hashlib
import re
from extract_scaler_geometry import ROOT, REF, COMMIT, extract

OUT = ROOT / 'driver/shim/generated/dc_mpc_blend.inc'

def generate():
    pieces = ['/* SPDX-License-Identifier: MIT */',
              '/* Generated by tools/import/extract_mpc_blend.py. Do not edit.\n'
              f' * PROVENANCE: Linux amdgpu DC, MIT, {COMMIT}. */']
    for name, functions in [('mpc.h', ()), ('dcn201_mpc.c', ('mpc201_init_mpcc',)),
                            ('dcn20_mpc.c', ('mpc2_update_blending',))]:
        raw = (REF / name).read_bytes()
        text = raw.decode('utf-8').replace('\r\n', '\n')
        pieces += [text[:text.index('*/') + 2],
                   f'/* {name}, sha256 {hashlib.sha256(raw).hexdigest()} */']
        if name == 'mpc.h':
            for enum in ('mpcc_blend_mode', 'mpcc_alpha_blend_mode'):
                match = re.findall(r'^enum ' + enum + r' \{.*?^\};', text, re.M | re.S)
                if len(match) != 1:
                    raise ValueError(enum)
                pieces.append(match[0])
        for function in functions:
            pieces.append(extract(text, function))
    return ('\n\n'.join(pieces).rstrip() + '\n').encode('utf-8')

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    expected = generate()
    if args.check:
        if OUT.read_bytes() != expected:
            raise SystemExit('MPC extraction mismatch')
    else:
        OUT.write_bytes(expected)
    print('MPC blend extraction OK')

if __name__ == '__main__':
    main()
